class EscenaSpec(BaseModel):
    """
    Escena estructurada de un percance vial, producida por el extractor LLM o editada por la persona. Es el único contrato entre extracción, croquis 2D, solver y visor. Cada dato lleva su procedencia (fuente, confianza y evidencia del relato). Unidades: el solver normaliza a SI; la interfaz muestra km/h y metros. Marco de referencia: metros, eje X al este, eje Y al norte, rumbo en grados desde +X en sentido antihorario.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    meta: Meta
    lugar: Lugar
    entorno: Entorno
    vehiculos: Annotated[list[Vehiculo], Field(max_length=8, min_length=0)]
    """
    Vehículos involucrados, incluidos los que no chocaron pero influyen (p. ej. uno estacionado va en entorno.objetos).
    """
    personas: Annotated[list[Persona], Field(max_length=32)]
    """
    Personas involucradas, sin nombres ni datos personales.
    """
    eventos: Annotated[list[Evento], Field(max_length=32)]
    """
    Secuencia temporal de lo que pasó. El evento de impacto principal tiene t = 0.
    """
    danos_declarados: Annotated[list[DanoDeclarado], Field(max_length=32)]
    evidencias: Annotated[list[EvidenciaFisica], Field(max_length=64)]
    expediente: Expediente | None = None
    """
    El expediente de CESVI (desde 2.0.0): opcional; una escena del relato no lo trae.
    """
